package com.zajel.app.data;

import com.zajel.app.core.AppExecutors;import com.zajel.app.core.SupabaseClient;import com.zajel.app.domain.*;import java.util.*;import org.json.*;
public final class SupabaseCommunityRepository implements CommunityRepository{
 private final SupabaseClient api;private final SecureSessionStore sessions;public SupabaseCommunityRepository(SupabaseClient a,SecureSessionStore s){api=a;sessions=s;}
 public void myCommunities(Callback<List<Community>> cb){load("/rest/v1/community_members?user_id=eq."+required().userId+"&select=communities(id,title,description,owner_id)",cb);}
 private void load(String p,Callback<List<Community>> cb){AppExecutors.network().execute(()->{try{JSONArray a=api.request("GET",p,required().accessToken,null).optJSONArray("rows");List<Community>o=new ArrayList<>();if(a!=null)for(int i=0;i<a.length();i++){JSONObject r=a.optJSONObject(i),x=r==null?null:r.optJSONObject("communities");if(x!=null)o.add(c(x));}cb.success(o);}catch(Exception e){cb.error(e);}});}
 public void create(String t,String d,Callback<Community>cb){AppExecutors.network().execute(()->{try{UserSession u=required();JSONObject r=first(api.request("POST","/rest/v1/communities",u.accessToken,new JSONObject().put("title",t).put("description",d).put("owner_id",u.userId)));if(r==null)throw new IllegalStateException("Community creation failed");api.request("POST","/rest/v1/community_members",u.accessToken,new JSONObject().put("community_id",r.optString("id")).put("user_id",u.userId).put("role","owner"));cb.success(c(r));}catch(Exception e){cb.error(e);}});}
 public void addGroup(String c,String g,Callback<Void>cb){link("community_groups",new JSONObject().put("community_id",c).put("group_id",g),cb);}public void addChannel(String c,String ch,Callback<Void>cb){link("community_channels",new JSONObject().put("community_id",c).put("channel_id",ch),cb);}
 private void link(String table,JSONObject b,Callback<Void>cb){AppExecutors.network().execute(()->{try{api.request("POST","/rest/v1/"+table,required().accessToken,b);cb.success(null);}catch(Exception e){cb.error(e);}});}
 public void linkedGroups(String id,Callback<List<String>>cb){ids("community_groups?community_id=eq."+id+"&select=group_id","group_id",cb);}public void linkedChannels(String id,Callback<List<String>>cb){ids("community_channels?community_id=eq."+id+"&select=channel_id","channel_id",cb);}
 private void ids(String p,String k,Callback<List<String>>cb){AppExecutors.network().execute(()->{try{JSONArray a=api.request("GET","/rest/v1/"+p,required().accessToken,null).optJSONArray("rows");List<String>o=new ArrayList<>();if(a!=null)for(int i=0;i<a.length();i++)o.add(a.optJSONObject(i).optString(k));cb.success(o);}catch(Exception e){cb.error(e);}});}
 private UserSession required(){UserSession u=sessions.read();if(u==null)throw new IllegalStateException("Not signed in");return u;}private JSONObject first(JSONObject x){JSONArray a=x.optJSONArray("rows");return a==null||a.length()==0?null:a.optJSONObject(0);}private Community c(JSONObject x){return new Community(x.optString("id"),x.optString("title"),x.optString("description"),x.optString("owner_id"));}
}
